export const Emoji: React.FC<{kind: EmojiKind; x: number; y: number; w: number; r?: number; o?: number; flip?: boolean}> = ({kind, x, y, w, r = 0, o = 1, flip}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${(w / 32) * (flip ? -1 : 1)} ${w / 32})`} opacity={o}>
    <g transform="translate(-16 -16)">
      {SHAPES[kind].map(([fill, d], i) => (
        <path key={i} d={d} fill={fill} />
      ))}
    </g>
  </g>
);
